    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const triggerQuickReply = (text) => {
                if (!text || ['…', '...'].includes(text.trim()) || text.trim().length === 0) return;
                if (typeof triggerSlash === 'function') triggerSlash(`/send ${text}|/trigger`);
                else console.log('SillyTavern environment not detected. Would send:', text);
            };

            initThemeToggle();
            const storyRenderer = new StoryRenderer('yaml-data-source');
            storyRenderer.init();

            document.getElementById('options-container').addEventListener('click', (e) => {
                const li = e.target.closest('li');
                if (li && li.closest('#options-list')) {
                    const optionText = li.textContent.trim();
                    triggerQuickReply(optionText);
                    const originalBg = li.style.backgroundColor;
                    li.style.backgroundColor = 'rgba(157, 124, 245, 0.2)';
                    setTimeout(() => { li.style.backgroundColor = originalBg; }, 300);
                }
            });
        });

        function initThemeToggle() {
            const themeButtons = document.querySelectorAll('.theme-btn');
            const themeContainer = document.getElementById('status-container');
            if (!themeContainer) {
                console.error("Theme container #status-container not found!");
                return;
            }

            const savedTheme = localStorage.getItem('storyTheme') || 'night';
            switchToTheme(savedTheme);

            themeButtons.forEach(button => {
                button.addEventListener('click', () => {
                    const theme = button.getAttribute('data-theme');
                    switchToTheme(theme);
                    localStorage.setItem('storyTheme', theme);
                });
            });

            function switchToTheme(theme) {
                // 重置容器的类
                themeContainer.className = "container mx-auto px-3 py-4 max-w-3xl";

                if (theme !== 'night') {
                   themeContainer.classList.add(`${theme}-mode`);
                }

                themeButtons.forEach(btn => btn.classList.toggle('active', btn.getAttribute('data-theme') === theme));
            }
        }

        class StoryRenderer {
            constructor(dataSourceId) {
                this.dataSourceId = dataSourceId;
                this.yamlData = null;
                this.rawYamlContent = "";
                this.rootNode = null;
                this.initElements();
                this.specialKeys = {
                    depravity: ['背德'],
                    lust: ['骚气']
                };
            }

            initElements() {
                this.elements = {
                    statusBarTitle: document.getElementById('status-bar-title'),
                    timeDisplay: document.getElementById('time-display'),
                    locationDisplay: document.getElementById('location-display'),
                    charactersContainer: document.getElementById('characters-container'),
                    actionOwner: document.getElementById('action-owner'),
                    optionsList: document.getElementById('options-list')
                };
            }

            init() {
                try {
                    this.loadYamlFromScriptTag();
                    this.findRootNode();
                    this.renderAll();
                    this.setupEventListeners();
                } catch (error) { this.handleError(error); }
            }

            loadYamlFromScriptTag() {
                const scriptElement = document.getElementById(this.dataSourceId);
                if (!scriptElement) throw new Error('未找到YAML数据源');
                this.rawYamlContent = scriptElement.textContent.trim();
                if (!this.rawYamlContent) throw new Error('YAML内容为空');
                try { this.yamlData = jsyaml.load(this.rawYamlContent); } catch (e) { throw new Error(`YAML解析错误: ${e.message}`); }
                if (!this.yamlData || Object.keys(this.yamlData).length === 0) throw new Error('YAML数据无效');
            }

            extractEmojis(text) {
                const emojiRegex = /[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu;
                return text.match(emojiRegex) || [];
            }

            getEmojiForField(fieldName) {
                const lines = this.rawYamlContent.split('\n');
                for (const line of lines) {
                    if (line.includes(fieldName) && line.includes(':')) {
                        const valuePart = line.split(':')[1].trim();
                        const emojis = this.extractEmojis(valuePart);
                        if (emojis.length > 0) return emojis[0];
                    }
                }
                return '📌';
            }

            parseValue(valueStr) {
                if (typeof valueStr !== 'string') return null;
                const match = valueStr.match(/(\d+)\s*\/\s*(\d+)/);
                if (match) {
                    return { current: parseInt(match[1]), max: parseInt(match[2]) };
                }
                return null;
            }

            findRootNode() {
                const rootNodeNames = Object.keys(this.yamlData);
                if (rootNodeNames.length === 0) throw new Error('YAML数据中未找到根节点');
                this.rootNode = rootNodeNames[0];
                this.elements.statusBarTitle.textContent = this.rootNode.charAt(0).toUpperCase() + this.rootNode.slice(1);
            }

            renderAll() {
                const rootData = this.yamlData[this.rootNode];
                if (!rootData) throw new Error('未找到有效的根节点数据');
                this.renderHeaderInfo(rootData);
                this.renderCharacters(rootData);
                this.renderActionOptions(rootData);
            }

            renderHeaderInfo(rootData) {
                const dateTimeField = Object.keys(rootData).find(k => k.includes('日期') || k.includes('时间'));
                const locationField = Object.keys(rootData).find(k => k.includes('地点'));

                if (dateTimeField) {
                    this.elements.timeDisplay.textContent = rootData[dateTimeField].replace(/[^\p{L}\p{N}\s:年日月]/gu, '');
                    this.elements.timeDisplay.parentNode.querySelector('.emoji').textContent = this.getEmojiForField(dateTimeField);
                }
                if (locationField) {
                    this.elements.locationDisplay.textContent = rootData[locationField].replace(/[^\p{L}\p{N}\s:]/gu, '');
                    this.elements.locationDisplay.parentNode.querySelector('.emoji').textContent = this.getEmojiForField(locationField);
                }
            }

            renderCharacters(rootData) {
                const userListField = Object.keys(rootData).find(k => k.toLowerCase().includes('用户列表'));
                const userList = userListField && Array.isArray(rootData[userListField]) ? rootData[userListField] : [];
                this.elements.charactersContainer.innerHTML = '';
                if (userList.length === 0) {
                    this.elements.charactersContainer.innerHTML = this.createEmptyState('没有角色数据');
                    return;
                }
                userList.forEach(userItem => {
                    const userData = userItem.用户 || userItem.user || userItem;
                    const characterCard = this.createCharacterCard(userData);
                    if (characterCard) this.elements.charactersContainer.appendChild(characterCard);
                });
            }

            createCharacterCard(userData) {
                if (!userData || typeof userData !== 'object') return null;
                const card = document.createElement('div');
                card.className = 'character-card bg-dark rounded-xl border border-gray-700/30 p-3.5 shadow-sm card-hover theme-transition';

                const nameField = Object.keys(userData).find(k => k.toLowerCase().includes('名字'));
                let userName = nameField ? userData[nameField] : '未知角色';
                const nameEmojis = this.extractEmojis(userName);
                const cleanName = userName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();

                const title = document.createElement('h3');
                title.className = 'font-bold text-lg mb-2 pb-1 border-b border-gray-700/30 theme-transition';
                title.innerHTML = `${nameEmojis.length > 0 ? nameEmojis[0] + ' ' : ''}${cleanName}的状态`;
                card.appendChild(title);

                const attributesList = document.createElement('ul');
                attributesList.className = 'space-y-2.5 text-sm';
                card.appendChild(attributesList);

                Object.keys(userData).filter(k => k !== nameField).forEach(key => {
                    const attributeItem = this.createAttributeItem(key, userData[key]);
                    if (attributeItem) attributesList.appendChild(attributeItem);
                });
                return card;
            }

            createAttributeItem(key, value) {
                const item = document.createElement('li');
                const emoji = this.getEmojiForField(key);
                let cleanValueText = (value || '').toString().replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();

                let specialType = null;
                if (this.specialKeys.depravity.some(k => key.includes(k))) specialType = 'depravity';
                if (this.specialKeys.lust.some(k => key.includes(k))) specialType = 'lust';
                const parsedValue = this.parseValue(cleanValueText);

                if (specialType && parsedValue) {
                    const percentage = (parsedValue.current / parsedValue.max) * 100;
                    item.innerHTML = `
                        <div class="flex items-center justify-between">
                            <span class="font-medium text-primary-value theme-transition">${emoji} ${key}:</span>
                            <span class="progress-value theme-transition">${parsedValue.current} / ${parsedValue.max}</span>
                        </div>
                        <div class="progress-bar-wrapper mt-1">
                            <div class="progress-bar ${specialType}" style="width: ${percentage}%; position: relative;"></div>
                        </div>
                    `;
                } else if (Array.isArray(value) || (typeof value === 'object' && value !== null)) {
                    item.innerHTML = `<span class="font-medium text-primary-value theme-transition">${emoji} ${key}:</span>`;
                    const subList = document.createElement('ul');
                    subList.className = 'list-disc list-inside ml-4 mt-1 space-y-1 text-gray-400 theme-transition';
                    const items = Array.isArray(value) ? value : Object.entries(value).map(([k,v]) => `${k}: ${v}`);
                    items.forEach(subItemData => {
                        const subItem = document.createElement('li');
                        subItem.textContent = subItemData.toString().trim();
                        subList.appendChild(subItem);
                    });
                    item.appendChild(subList);
                } else {
                    item.innerHTML = `<span class="font-medium text-primary-value theme-transition">${emoji} ${key}:</span><span class="text-gray-300"> ${cleanValueText}</span>`;
                }
                return item;
            }

            renderActionOptions(rootData) {
                const actionOptionsField = Object.keys(rootData).find(k => k.toLowerCase().includes('行动选项'));
                const actionOptions = actionOptionsField ? rootData[actionOptionsField] : {};
                const ownerField = Object.keys(actionOptions).find(k => k.toLowerCase().includes('名字'));
                let ownerName = ownerField ? actionOptions[ownerField] : '未知角色';
                const ownerEmojis = this.extractEmojis(ownerName);
                const cleanOwnerName = ownerName.replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
                this.elements.actionOwner.innerHTML = `${ownerEmojis.length > 0 ? ownerEmojis[0] + ' ' : ''}${cleanOwnerName}`;
                const optionsField = Object.keys(actionOptions).find(k => k.toLowerCase().includes('选项'));
                const options = optionsField && Array.isArray(actionOptions[optionsField]) ? actionOptions[optionsField] : [];
                this.elements.optionsList.innerHTML = '';

                if (options.length === 0) {
                    this.elements.optionsList.innerHTML = this.createEmptyState('没有可用选项');
                    return;
                }

                options.forEach(optionText => {
                    const optionEmojis = this.extractEmojis(optionText);
                    const cleanOptionText = optionText.replace(/^\d+\.\s*/, '').replace(/[\u{1F600}-\u{1F64F}\u{1F300}-\u{1F5FF}\u{1F680}-\u{1F6FF}\u{1F1E0}-\u{1F1FF}\u{2600}-\u{26FF}\u{2700}-\u{27BF}]/gu, '').trim();
                    const optionItem = document.createElement('li');
                    optionItem.className = 'pl-2 py-1.5 border-l-2 border-primary/30 ml-1 hover:border-primary/70 transition-colors text-gray-300 theme-transition';
                    optionItem.innerHTML = `${optionEmojis.length > 0 ? optionEmojis[0] + ' ' : ''}${cleanOptionText}`;
                    this.elements.optionsList.appendChild(optionItem);
                });
            }

            createEmptyState(message) {
                return `<div class="text-center py-4 text-gray-500 theme-transition"><i class="fa fa-info-circle mr-1"></i>${message}</div>`;
            }

            setupEventListeners() {
                const detailsElement = document.querySelector('details');
                const contentElement = this.elements.charactersContainer;
                contentElement.style.maxHeight = '0px';
                detailsElement.addEventListener('toggle', () => {
                    contentElement.style.maxHeight = detailsElement.open ? `${contentElement.scrollHeight}px` : '0px';
                });
                detailsElement.open = true; // 默认展开方便调试
            }

            handleError(error) {
                console.error('渲染错误:', error);
                this.elements.charactersContainer.innerHTML = `<div class="bg-red-900/20 border border-red-800/30 text-red-400 px-4 py-3 rounded" role="alert"><strong class="font-bold">加载失败: </strong><span>${error.message}</span></div>`;
            }
        }
    </script>
